import { matchPricingToCapabilities } from "../pricing.js";
/**
 * Generates MPP challenges by matching pricing entries to handlers.
 *
 * For each handler, matches pricing by capabilities, then calls
 * getChallenge for each matched pricing entry and each supported
 * intent. The middleware emits all challenges; the client picks one.
 */
export async function resolveMPPChallenges(handlers, pricing, resourceURL, opts) {
    const results = [];
    for (const handler of handlers) {
        const matched = matchPricingToCapabilities(handler.capabilities, pricing);
        if (matched.length === 0) {
            opts?.logger?.warning("no pricing matched handler capabilities for MPP challenge generation", { method: handler.method });
            continue;
        }
        const intents = handler.getSupportedIntents();
        if (intents.length === 0) {
            opts?.logger?.warning("MPP handler declares no supported intents", {
                method: handler.method,
            });
            continue;
        }
        for (const p of matched) {
            for (const intent of intents) {
                const challengeOpts = {};
                if (opts?.digest !== undefined)
                    challengeOpts.digest = opts.digest;
                const challenge = await handler.getChallenge(intent, p, resourceURL, challengeOpts);
                results.push(challenge);
            }
        }
    }
    return results;
}
/**
 * Routes an MPP credential to the appropriate handler for settlement.
 *
 * Filters handlers by exact method match against the credential's
 * challenge method, then iterates handleSettle until one returns a
 * non-null result.
 */
export async function settleMPPPayment(handlers, credential) {
    const method = credential.challenge.method;
    const candidates = handlers.filter((h) => h.method === method);
    for (const handler of candidates) {
        const result = await handler.handleSettle(credential);
        if (result)
            return result;
    }
    throw new Error(`no MPP handler accepted settlement for method "${method}"`);
}
/**
 * Routes an MPP credential to the appropriate handler for verification.
 *
 * Filters handlers by exact method match and presence of handleVerify,
 * then iterates until one returns a non-null result.
 */
export async function verifyMPPPayment(handlers, credential) {
    const method = credential.challenge.method;
    const candidates = handlers.filter((h) => h.method === method && h.handleVerify !== undefined);
    if (candidates.length === 0) {
        throw new Error(`no MPP handler supports verification for method "${method}"`);
    }
    for (const handler of candidates) {
        const result = await handler.handleVerify(credential);
        if (result)
            return result;
    }
    throw new Error(`no MPP handler accepted verification for method "${method}"`);
}
